<?php declare(strict_types=1);
require_once __DIR__.'/original-database-hash.php';
function ownInvoiceFilesDb():PDO{$cfg=\Kulturhus\Native\TestSupport::config();$db=\Kulturhus\Native\TestSupport::db();if(($cfg['owner']??'')!=='isolated-native-ci'||($cfg['label']??'')!=='native-inventory-invoice-files-interface'||!preg_match('/\Akh_native_[a-f0-9]{24}\z/D',$cfg['database']??'')||$db->query('SELECT DATABASE()')->fetchColumn()!==$cfg['database'])throw new RuntimeException('Owned invoice files required.');return$db;}
function ownInvoiceFilesProof():void{
 $db=ownInvoiceFilesDb();$tables=array_values(array_diff($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN),['native_auth_sessions','native_auth_limits','native_language_preferences']));$whole=ownOriginalDatabaseHash($db,$tables);$docs=$db->query("SELECT d.*,f.name,f.sha256,f.mime FROM documents d JOIN document_files f ON f.club_id=d.club_id AND f.document_id=d.id AND f.revision=1 WHERE d.club_id='own-list-club' ORDER BY d.id")->fetchAll(PDO::FETCH_ASSOC);$links=$db->query("SELECT * FROM document_links WHERE club_id='own-list-club' ORDER BY document_id,source_type,source_id")->fetchAll(PDO::FETCH_ASSOC);$balances=array_column((new \Kulturhus\Verein\Finance($db,'own-list-admin'))->accounts(),'balance_cents','id');header('Content-Type: application/json');header('Cache-Control: no-store');echo json_encode(compact('whole','docs','links','balances'),JSON_THROW_ON_ERROR);
}
function ownInvoiceFilesFault(array$f):void{
 $db=ownInvoiceFilesDb();if(($_SERVER['REQUEST_METHOD']??'')!=='POST'||!hash_equals($f['data']['fault_token'],$_SERVER['HTTP_X_OWNED_INVOICE_FILES_FAULT']??'')||!in_array($_POST['mode']??null,['on','off'],true)){http_response_code(403);exit;}$db->exec('DROP TRIGGER IF EXISTS own_invoice_files_browser_failure');if($_POST['mode']==='on')$db->exec("CREATE TRIGGER own_invoice_files_browser_failure BEFORE INSERT ON audit_events FOR EACH ROW BEGIN IF NEW.action='document.uploaded' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Own actual browser financial file audit failure'; END IF; END");header('Content-Type: application/json');echo'{"ok":true}';
}
